"""Install the separate Grid-only target-stop workflow and launch it on Dantzig."""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import sys
import zlib

PAYLOAD = ''
PAYLOAD_SHA256 = '96f55c8b271b814eb96c75466557a81b44c9902c73ed117096f2d9eb07eea904'
SERVER_REPO = Path("/local/scratch/a/lee4382/repository/RBFopt_Test")

def install(repo):
    raw=zlib.decompress(base64.b64decode(PAYLOAD))
    if hashlib.sha256(raw).hexdigest()!=PAYLOAD_SHA256:
        raise ValueError("Installer payload hash mismatch")
    files=json.loads(raw)
    if any(PurePosixPath(n).is_absolute() or '..' in PurePosixPath(n).parts for n in files):
        raise ValueError("Invalid installation path")
    destination=repo/'experiments/dsda_grid_target_stop'
    if destination.exists():
        for name,content in files.items():
            p=destination/name
            if not p.is_file() or p.read_bytes()!=content.encode():
                raise ValueError("Existing workflow differs; preserving it: "+str(p))
        print("EXISTING_IDENTICAL_INSTALLATION",destination,flush=True)
        return destination
    staging=repo/'experiments'/('.dsda_grid_target_stop_install_'+str(os.getpid()))
    staging.mkdir(parents=True,exist_ok=False)
    for name,content in files.items():
        p=staging/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(content.encode())
    (staging/'INSTALL.json').write_text(json.dumps(dict(payload_sha256=PAYLOAD_SHA256,files_sha256={n:hashlib.sha256(v.encode()).hexdigest() for n,v in files.items()},expected_grid_jobs=1050,process_jobs=0),indent=2)+'\n')
    staging.rename(destination)
    print("INSTALLED",destination,flush=True)
    return destination

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--install-only',action='store_true')
    parser.add_argument('--resume',type=Path)
    args=parser.parse_args()
    repo=Path(__file__).resolve().parent
    if repo!=SERVER_REPO:
        raise RuntimeError("Place this installer in the Dantzig RBFopt_Test repository root")
    if Path(sys.executable).absolute()!=repo/'.venv-dantzig/bin/python':
        raise RuntimeError("Use the existing .venv-dantzig/bin/python")
    installed=install(repo)
    if args.install_only:
        print("INSTALL_ONLY; no Grid search started.",flush=True)
        return
    command=[sys.executable,str(installed/'launch.py')]
    if args.resume:command+=['--resume',str(args.resume)]
    os.environ['PYTHONDONTWRITEBYTECODE']='1'
    os.execv(sys.executable,command)

if __name__=='__main__':
    main()
